def binary_search(values, target):
    lo = 0
    hi = len(values) - 1

    while lo <= hi:
        mid = (lo + hi) // 2

        if values[mid] == target:
            return mid
        elif values[mid] < target:
            lo = mid + 1
        else:
            hi = mid - 1

    return -1

def selection_sort(values):
    a = values.copy()

    for i in range(len(a)):
        min_index = i

        for j in range(i + 1, len(a)):
            if a[j] < a[min_index]:
                min_index = j

        a[i], a[min_index] = a[min_index], a[i]

    return a

