def permutations(values):
    result = []

    def backtrack(path, remaining):
        if not remaining:
            result.append(path.copy())
            return

        for i, value in enumerate(remaining):
            path.append(value)
            backtrack(
                path,
                remaining[:i] + remaining[i+1:]
            )
            path.pop()

    backtrack([], values)
    return result

